/* =================================== */
/* 🛠️ 小白专属补丁：底栏整体与内容上下调节 */
/* =================================== */
:root {
  /* 👇 1. 控制“输入框”和“白色背景”整体抬起的高度 */
  /* 原版默认是 50px。数值越大，输入框被顶得越高，底部的白边越厚 */
  --new-bottom-height: 70px; 

  /* 👇 2. 控制最下面“一排6个小图标”跟着抬起的高度 */
  /* 原版默认是 12px。如果上面的输入框抬高了，小图标也要跟着加大数值，避免离得太远 */
  --new-icon-bottom: 25px; 
}

/* --- 自动执行区（小白不用管下面） --- */
/* 强制覆盖原有的底栏高度 */
.input-area-custom {
    padding-bottom: var(--new-bottom-height) !important;
}

/* 强制覆盖6个小图标的底部距离 */
.input-area-custom::after {
    bottom: var(--new-icon-bottom) !important;
}
/* =================================== */
/* 🛠️ 小白专属补丁：单独抬高底栏 6 个图标 */
/* =================================== */
:root {
  /* 👇 6个小图标距离底部的距离 */
  /* 之前默认是 25px。把数值改大（例如改成 35px ），图标就会整体往上挪！ */
  --new-icon-bottom: 25px; 
}

/* 强制更新 6 个图标的位置 */
.input-area-custom::after {
    bottom: var(--new-icon-bottom) !important;
}

/* =========================================================
   🛠️ 引用框纯净版防溢出补丁
   ========================================================= */
.msg-reply-block-detached {
    display: flex !important;
    align-items: center !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    width: fit-content !important;
    max-width: calc(100vw - 180px) !important;
    min-width: 0 !important;
    box-sizing: border-box !important;
    overflow: hidden !important;
}

.msg-me .msg-reply-block-detached img,
.msg-them .msg-reply-block-detached img,
.msg-reply-block-detached img {
    width: 30px !important;
    height: 30px !important;
    min-width: 30px !important;
    min-height: 30px !important;
    max-width: 30px !important;
    max-height: 30px !important;
    object-fit: cover !important;
    border-radius: 4px !important;
    flex-shrink: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    display: block !important;
    position: static !important;
    transform: none !important;
}

.msg-reply-detached-text,
.msg-reply-detached-content,
.msg-reply-block-detached span:not(.msg-reply-detached-name) {
    flex: 1 1 auto !important;
    min-width: 0 !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
    word-break: break-all !important;
}

/* =======================================
   📏 8️⃣ 限制常规气泡最大宽度
   ======================================= */
.bubble-me-custom,
.bubble-them-custom {
    max-width: 72vw !important;
    box-sizing: border-box !important;
    word-wrap: break-word !important;
    word-break: break-word !important;
}

/* ========== 表情包单独缩小 ========== */
.bubble-me-custom img,
.bubble-them-custom img,
.msg-plain-me img,
.msg-plain-them img {
    max-width: 110px !important;
    max-height: 110px !important;
    width: auto !important;
    height: auto !important;
    object-fit: contain !important;
    border-radius: 5px !important;
}

/* ========== 普通图片单独缩小 ========== */
.msg-image-wrapper img,
.msg-bubble-wrapper .msg-image-wrapper img {
    max-width: 170px !important;
    max-height: 170px !important;
    width: auto !important;
    height: auto !important;
    object-fit: cover !important;
    border-radius: 5px !important;
}

/* 去除非文字独立消息气泡 */
:is(.msg-plain-me, .msg-plain-them, .bubble-me-custom, .bubble-them-custom,
    .msg-bubble-container, [class*="bubble"]):has(
    [class*="image"], [class*="picture"], [class*="sticker"], [class*="emoji"],
    [class*="face"], [class*="card"], [class*="transfer"], [class*="gift"],
    [class*="location"], [class*="file"], [class*="videocall"],
    [class*="voice-call"], [class*="voicecall"], [class*="call-card"], img
):not(:has(
    .msg-reply-block,
    .msg-reply-block-detached,
    [class*="reply"],
    [class*="quote"],
    [class*="avatar"],
    p,
    .msg-text,
    .text-content,
    [class*="voice"]:not([class*="videocall"], [class*="voice-call"],
        [class*="voicecall"], [class*="call-card"])
)) {
    background: transparent none !important;
    border: 0 none !important;
    border-image: none !important;
